"""Generated by the scripted agent. Functions covered: remove_item, low_stock, total_value, restock_plan."""
import unittest

from inventory.stock import low_stock, remove_item, restock_plan, total_value


class GeneratedStockTests(unittest.TestCase):
    def test_remove_item_rejects_overdraw(self):
        with self.assertRaises(ValueError):
            remove_item({"a": 1}, "a", 2)

    def test_low_stock_is_sorted(self):
        self.assertEqual(low_stock({"b": 1, "a": 2, "c": 9}, threshold=5), ["a", "b"])

    def test_total_value_sums(self):
        self.assertEqual(total_value({"a": 2, "b": 1}, {"a": 1.5, "b": 2.25}), 5.25)

    def test_total_value_needs_a_price(self):
        with self.assertRaises(KeyError):
            total_value({"a": 1}, {})

    def test_restock_plan_tops_up(self):
        self.assertEqual(restock_plan({"a": 1, "b": 7}, target=5), {"a": 4})


if __name__ == "__main__":
    unittest.main()
